1	// pattern: Imperative Shell
2	//
3	// The auth.md agent claim ceremony (spec Step 4). Two endpoints, split by audience:
4	//
5	//   - `POST /agent/identity/claim` — the *agent* starts (or resumes) a ceremony for a registration
6	//     it holds a `claim_token` for. Public: the `claim_token` is the agent's credential, so no user
7	//     session is required here. Mainly serves the `anonymous` flow, whose registration returned only
8	//     a `claim_token` and no `user_code`; `service_auth` / first-seen `identity_assertion` already
9	//     minted a `user_code` at registration, so re-initiating idempotently re-emits the pending one.
10	//   - `POST /agent/identity/claim/confirm` — the *account owner* (full-access session/OAuth token)
11	//     submits the `user_code` the agent showed them. This binds the registration to their DID (for
12	//     an ownerless `anonymous` identity), mints the post-claim `identity_assertion`, and flips the
13	//     identity `active → claimed` so its assertion can be exchanged at the token endpoint. This is
14	//     the wallet-facing surface (Obsign's claim-approval screen).
15	//
16	// Registration lives in `agent_identity.rs`; the assertion-minting / claim-block / error helpers are
17	// shared via `auth::agent_assertion` (routes may not import from one another).
18	
19	use axum::{
20	    extract::State,
21	    http::StatusCode,
22	    response::{IntoResponse, Response},
23	    Json,
24	};
25	use chrono::{Duration, SecondsFormat, Utc};
26	use serde::{Deserialize, Serialize};
27	
28	use crate::app::AppState;
29	use crate::auth::agent_assertion::{
30	    mint_identity_assertion, new_claim_attempt_id, parse_sqlite_datetime, scopes_to_json,
31	    to_sqlite_datetime, verification_uri, AgentAuthError,
32	};
33	use crate::auth::extractors::AuthenticatedUser;
34	use crate::auth::jwt::AuthScope;
35	use crate::auth::oauth_scopes::intersect_scope_tokens;
36	use crate::code_gen::generate_code;
37	use crate::db::agent_auth::{
38	    claim_agent_identity, complete_agent_claim_attempt, get_agent_claim_attempt_by_user_code,
39	    get_agent_identity, get_agent_identity_by_claim_token, insert_agent_claim_attempt,
40	    latest_agent_claim_attempt_for_identity, AgentIdentityStatus, ClaimAttemptStatus,
41	    NewAgentClaimAttempt,
42	};
43	
44	/// Seconds an agent should wait between claim-status polls (the auth.md claim block `interval`). The
45	/// machine-pollable claim grant that consumes it is a separate ticket; the value is advertised now
46	/// so a polling client can pace itself once that lands.
47	const POLL_INTERVAL_SECS: u64 = 5;
48	
49	// ── POST /agent/identity/claim (initiate) ─────────────────────────────────────
50	
51	#[derive(Debug, Deserialize)]
52	pub struct ClaimInitiateRequest {
53	    pub claim_token: Option<String>,
54	    /// Optional email the user wants the ceremony associated with (informational; the binding is by
55	    /// the confirming user's authenticated DID, not this field).
56	    #[serde(default)]
57	    pub email: Option<String>,
58	}
59	
60	#[derive(Debug, Serialize)]
61	struct ClaimAttemptBlock {
62	    user_code: String,
63	    expires_in: i64,
64	    verification_uri: String,
65	    interval: u64,
66	}
67	
68	#[derive(Debug, Serialize)]
69	struct ClaimInitiateResponse {
70	    registration_id: String,
71	    claim_attempt_id: String,
72	    status: &'static str,
73	    expires_at: String,
74	    claim_attempt: ClaimAttemptBlock,
75	}
76	
77	/// `POST /agent/identity/claim` — start or resume a claim ceremony (no auth; the `claim_token` is
78	/// the credential).
79	pub async fn post_agent_claim(
80	    State(state): State<AppState>,
81	    Json(req): Json<ClaimInitiateRequest>,
82	) -> Response {
83	    match initiate(&state, &req).await {
84	        Ok(response) => response,
85	        Err(err) => err.into_response(),
86	    }
87	}
88	
89	async fn initiate(
90	    state: &AppState,
91	    req: &ClaimInitiateRequest,
92	) -> Result<Response, AgentAuthError> {
93	    let claim_token = req
94	        .claim_token
95	        .as_deref()
96	        .filter(|s| !s.is_empty())
97	        .ok_or_else(|| {
98	            AgentAuthError::new(
99	                StatusCode::BAD_REQUEST,
100	                "invalid_request",
101	                "missing required field: claim_token",
102	            )
103	        })?;
104	
105	    let identity = get_agent_identity_by_claim_token(&state.db, claim_token)
106	        .await?
107	        .ok_or_else(|| {
108	            AgentAuthError::new(
109	                StatusCode::BAD_REQUEST,
110	                "invalid_claim_token",
111	                "the claim token is unknown",
112	            )
113	        })?;
114	
115	    match identity.status {
116	        AgentIdentityStatus::Claimed => {
117	            return Err(AgentAuthError::new(
118	                StatusCode::BAD_REQUEST,
119	                "claimed_or_in_flight",
120	                "this registration has already been claimed",
121	            ));
122	        }
123	        // A revoked identity is not distinguished from an unknown token (don't leak state).
124	        AgentIdentityStatus::Revoked => {
125	            return Err(AgentAuthError::new(
126	                StatusCode::BAD_REQUEST,
127	                "invalid_claim_token",
128	                "the claim token is unknown",
129	            ));
130	        }
131	        AgentIdentityStatus::Active => {}
132	    }
133	
134	    // The claim token has its own TTL (the auth.md pre-claim window). Its stored expiry uses the
135	    // sqlite `YYYY-MM-DD HH:MM:SS` format, which sorts chronologically, so a lexicographic compare
136	    // against "now" in the same format is a correct expiry check.
137	    let now_sqlite = to_sqlite_datetime(&Utc::now());
138	    if identity
139	        .claim_token_expires_at
140	        .as_deref()
141	        .map(|exp| exp <= now_sqlite.as_str())
142	        .unwrap_or(false)
143	    {
144	        return Err(AgentAuthError::new(
145	            StatusCode::BAD_REQUEST,
146	            "claim_expired",
147	            "the claim token has expired; re-register",
148	        ));
149	    }
150	
151	    // Resume an in-flight ceremony rather than minting a second user_code: an agent that lost the
152	    // response, or is polling, gets the same code back. Otherwise open a fresh attempt.
153	    let (attempt_id, user_code, expiry) =
154	        match latest_agent_claim_attempt_for_identity(&state.db, &identity.id).await? {
155	            Some(attempt) if attempt.is_pending() => (
156	                attempt.id,
157	                attempt.user_code,
158	                parse_sqlite_datetime(&attempt.user_code_expires_at),
159	            ),
160	            _ => {
161	                let attempt_id = new_claim_attempt_id();
162	                let user_code = generate_code();
163	                let expiry = Utc::now()
164	                    + Duration::seconds(state.config.agent_auth.user_code_ttl_secs as i64);
165	                insert_agent_claim_attempt(
166	                    &state.db,
167	                    &NewAgentClaimAttempt {
168	                        id: &attempt_id,
169	                        identity_id: &identity.id,
170	                        user_code: &user_code,
171	                        user_code_expires_at: &to_sqlite_datetime(&expiry),
172	                        email: req.email.as_deref().or(identity.email.as_deref()),
173	                    },
174	                )
175	                .await?;
176	                (attempt_id, user_code, expiry)
177	            }
178	        };
179	
180	    let expires_in = (expiry - Utc::now()).num_seconds().max(0);
181	    let body = ClaimInitiateResponse {
182	        registration_id: identity.id,
183	        claim_attempt_id: attempt_id,
184	        status: "initiated",
185	        expires_at: expiry.to_rfc3339_opts(SecondsFormat::Millis, true),
186	        claim_attempt: ClaimAttemptBlock {
187	            user_code,
188	            expires_in,
189	            verification_uri: verification_uri(&state.config.agent_auth, &state.config.public_url),
190	            interval: POLL_INTERVAL_SECS,
191	        },
192	    };
193	    Ok((StatusCode::OK, Json(body)).into_response())
194	}
195	
196	// ── POST /agent/identity/claim/confirm (confirm) ──────────────────────────────
197	
198	#[derive(Debug, Deserialize)]
199	pub struct ClaimConfirmRequest {
200	    pub user_code: Option<String>,
201	    /// Optional cross-check: when present, must name the registration this `user_code` belongs to.
202	    #[serde(default)]
203	    pub registration_id: Option<String>,
204	}
205	
206	#[derive(Debug, Serialize)]
207	struct ClaimConfirmResponse {
208	    registration_id: String,
209	    status: &'static str,
210	    did: String,
211	}
212	
213	/// `POST /agent/identity/claim/confirm` — the account owner confirms a claim (full-access authed).
214	pub async fn post_agent_claim_confirm(
215	    user: AuthenticatedUser,
216	    State(state): State<AppState>,
217	    Json(req): Json<ClaimConfirmRequest>,
218	) -> Response {
219	    match confirm(user, &state, &req).await {
220	        Ok(response) => response,
221	        Err(err) => err.into_response(),
222	    }
223	}
224	
225	async fn confirm(
226	    user: AuthenticatedUser,
227	    state: &AppState,
228	    req: &ClaimConfirmRequest,
229	) -> Result<Response, AgentAuthError> {
230	    // Only the account holder's own full-access credential may confirm. App-password tokens
231	    // (narrower scope) are refused by the scope check; agent-derived tokens map to `Access` for
232	    // coarse admission, so `is_agent` closes the gap — an agent must never confirm itself.
233	    if user.scope != AuthScope::Access {
234	        return Err(AgentAuthError::new(
235	            StatusCode::UNAUTHORIZED,
236	            "invalid_token",
237	            "a full-access token is required to confirm an agent claim",
238	        ));
239	    }
240	    if user.is_agent() {
241	        return Err(AgentAuthError::new(
242	            StatusCode::FORBIDDEN,
243	            "access_denied",
244	            "agent-derived credentials cannot confirm a claim",
245	        ));
246	    }
247	
248	    let user_code = req
249	        .user_code
250	        .as_deref()
251	        .filter(|s| !s.is_empty())
252	        .ok_or_else(|| {
253	            AgentAuthError::new(
254	                StatusCode::BAD_REQUEST,
255	                "invalid_request",
256	                "missing required field: user_code",
257	            )
258	        })?;
259	
260	    // Brute-forcing the `user_code` is bounded today by the global per-IP rate limiter, and this
261	    // endpoint is already full-access authenticated — so the guessing surface is an *authenticated*
262	    // caller racing a ~36^6-wide code within its short TTL (and success only lets them bind an
263	    // ownerless anonymous registration to their own account, not take over a victim's). A dedicated
264	    // per-code failure lockout is intentionally left to the follow-on wallet agent-consent/audit
265	    // hardening work, which owns claim rate-limiting — consistent with the sibling short-code
266	    // surface `/v1/transfer/accept`, which likewise relies on the shared limiter.
267	    let attempt = get_agent_claim_attempt_by_user_code(&state.db, user_code)
268	        .await?
269	        .ok_or_else(|| {
270	            AgentAuthError::new(
271	                StatusCode::BAD_REQUEST,
272	                "invalid_user_code",
273	                "the user code is unknown",
274	            )
275	        })?;
276	    if !attempt.is_pending() {
277	        // An already-consumed attempt is `claimed_or_in_flight`; anything else non-pending (swept
278	        // expired, or pending-but-past-expiry) is a lapsed code.
279	        return Err(if attempt.status == ClaimAttemptStatus::Completed {
280	            AgentAuthError::new(
281	                StatusCode::BAD_REQUEST,
282	                "claimed_or_in_flight",
283	                "this user code has already been used",
284	            )
285	        } else {
286	            AgentAuthError::new(
287	                StatusCode::BAD_REQUEST,
288	                "claim_expired",
289	                "the user code has expired; restart the claim",
290	            )
291	        });
292	    }
293	
294	    let identity = get_agent_identity(&state.db, &attempt.identity_id)
295	        .await?
296	        .ok_or_else(AgentAuthError::server_error)?;
297	
298	    if let Some(req_reg) = req.registration_id.as_deref().filter(|s| !s.is_empty()) {
299	        if req_reg != identity.id {
300	            return Err(AgentAuthError::new(
301	                StatusCode::BAD_REQUEST,
302	                "invalid_request",
303	                "registration_id does not match this user code",
304	            ));
305	        }
306	    }
307	
308	    match identity.status {
309	        AgentIdentityStatus::Claimed => {
310	            return Err(AgentAuthError::new(
311	                StatusCode::BAD_REQUEST,
312	                "claimed_or_in_flight",
313	                "this registration has already been claimed",
314	            ));
315	        }
316	        AgentIdentityStatus::Revoked => {
317	            return Err(AgentAuthError::new(
318	                StatusCode::FORBIDDEN,
319	                "access_denied",
320	                "this agent identity has been revoked",
321	            ));
322	        }
323	        AgentIdentityStatus::Active => {}
324	    }
325	
326	    // Authorization. A registration already bound to an owner (service_auth / identity_assertion)
327	    // may be confirmed only by that owner. An ownerless anonymous registration is bound to whoever
328	    // completes the ceremony — the `user_code` they were shown is the authorization.
329	    let bind_did = match identity.did.as_deref() {
330	        Some(bound) => {
331	            if bound != user.did {
332	                return Err(AgentAuthError::new(
333	                    StatusCode::FORBIDDEN,
334	                    "access_denied",
335	                    "this claim is bound to a different account",
336	                ));
337	            }
338	            None
339	        }
340	        None => Some(user.did.as_str()),
341	    };
342	
343	    // The post-claim assertion carries the operator's current full granted-scope profile. Normalize
344	    // it into a deterministic, deduplicated set so this mint matches the `identity_assertion` mint
345	    // path byte-for-byte: `intersect_scope_tokens(xs, xs)` is the crate's canonicalizer — it returns
346	    // the tokens of `xs` sorted and deduped (a self-intersection, since every token is in both
347	    // operands). There is no separate infallible canonicalizer helper; `canonicalize_agent_scopes`
348	    // is the fallible startup validator, not this hot path.
349	    let granted = &state.config.agent_auth.granted_scopes;
350	    let scopes = intersect_scope_tokens(granted, granted);
351	    let minted = mint_identity_assertion(
352	        &state.oauth_signing_keypair,
353	        &state.config.public_url,
354	        state.config.agent_auth.assertion_ttl_secs,
355	        &user.did,
356	        &identity.id,
357	        identity.registration_type.as_str(),
358	        &scopes,
359	    )?;
360	    let scopes_json = scopes_to_json(&scopes);
361	
362	    // One transaction: consume the pending attempt, then claim the identity. Each write carries its
363	    // own guard (`status = 'pending'` / `status = 'active'`), so a lost race rolls back cleanly
364	    // rather than double-claiming. Every read (and the pure mint) ran before `begin()` — the
365	    // single-connection pool cannot serve a `&SqlitePool` read while a transaction holds the
366	    // connection.
367	    let mut tx = state.db.begin().await.map_err(|e| {
368	        tracing::error!(error = %e, "failed to open transaction for agent claim confirm");
369	        AgentAuthError::server_error()
370	    })?;
371	    if !complete_agent_claim_attempt(&mut *tx, &attempt.id).await? {
372	        return Err(AgentAuthError::new(
373	            StatusCode::CONFLICT,
374	            "claimed_or_in_flight",
375	            "this claim attempt is no longer pending",
376	        ));
377	    }
378	    if !claim_agent_identity(
379	        &mut *tx,
380	        &identity.id,
381	        bind_did,
382	        &scopes_json,
383	        &minted.jwt,
384	        &minted.expires_sqlite,
385	    )
386	    .await?
387	    {
388	        return Err(AgentAuthError::new(
389	            StatusCode::CONFLICT,
390	            "claimed_or_in_flight",
391	            "this registration is no longer active",
392	        ));
393	    }
394	    tx.commit().await.map_err(|e| {
395	        tracing::error!(error = %e, "failed to commit agent claim confirm");
396	        AgentAuthError::server_error()
397	    })?;
398	
399	    Ok((
400	        StatusCode::OK,
401	        Json(ClaimConfirmResponse {
402	            registration_id: identity.id,
403	            status: "claimed",
404	            did: user.did,
405	        }),
406	    )
407	        .into_response())
408	}
