    NewAgentClaimAttempt,
};

/// Seconds an agent should wait between claim-status polls (the auth.md claim block `interval`). The
/// machine-pollable claim grant that consumes it is a separate ticket; the value is advertised now
/// so a polling client can pace itself once that lands.
const POLL_INTERVAL_SECS: u64 = 5;

// ── POST /agent/identity/claim (initiate) ─────────────────────────────────────

#[derive(Debug, Deserialize)]
pub struct ClaimInitiateRequest {
    pub claim_token: Option<String>,
    /// Optional email the user wants the ceremony associated with (informational; the binding is by
    /// the confirming user's authenticated DID, not this field).
    #[serde(default)]
    pub email: Option<String>,
}

#[derive(Debug, Serialize)]
struct ClaimAttemptBlock {
    user_code: String,
    expires_in: i64,
    verification_uri: String,
    interval: u64,
}

#[derive(Debug, Serialize)]
struct ClaimInitiateResponse {
    registration_id: String,
    claim_attempt_id: String,
    status: &'static str,
    expires_at: String,
    claim_attempt: ClaimAttemptBlock,
}

/// `POST /agent/identity/claim` — start or resume a claim ceremony (no auth; the `claim_token` is
/// the credential).
pub async fn post_agent_claim(
    State(state): State<AppState>,
    Json(req): Json<ClaimInitiateRequest>,
) -> Response {
    match initiate(&state, &req).await {
        Ok(response) => response,
        Err(err) => err.into_response(),
    }
}

async fn initiate(
    state: &AppState,
    req: &ClaimInitiateRequest,
) -> Result<Response, AgentAuthError> {
    let claim_token = req
        .claim_token
        .as_deref()
        .filter(|s| !s.is_empty())
        .ok_or_else(|| {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_request",
                "missing required field: claim_token",
            )
        })?;

    let identity = get_agent_identity_by_claim_token(&state.db, claim_token)
        .await?
        .ok_or_else(|| {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_claim_token",
                "the claim token is unknown",
            )
        })?;

    match identity.status {
        AgentIdentityStatus::Claimed => {
            return Err(AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "claimed_or_in_flight",
                "this registration has already been claimed",
            ));
        }
        // A revoked identity is not distinguished from an unknown token (don't leak state).
        AgentIdentityStatus::Revoked => {
            return Err(AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_claim_token",
                "the claim token is unknown",
            ));
        }
        AgentIdentityStatus::Active => {}
    }

    // The claim token has its own TTL (the auth.md pre-claim window). Its stored expiry uses the
    // sqlite `YYYY-MM-DD HH:MM:SS` format, which sorts chronologically, so a lexicographic compare
    // against "now" in the same format is a correct expiry check.
    let now_sqlite = to_sqlite_datetime(&Utc::now());
    if identity
        .claim_token_expires_at
        .as_deref()
        .map(|exp| exp <= now_sqlite.as_str())
        .unwrap_or(false)
    {
        return Err(AgentAuthError::new(
            StatusCode::BAD_REQUEST,
            "claim_expired",
            "the claim token has expired; re-register",
        ));
    }

    // Resume an in-flight ceremony rather than minting a second user_code: an agent that lost the
    // response, or is polling, gets the same code back. Otherwise open a fresh attempt.
    let (attempt_id, user_code, expiry) =
        match latest_agent_claim_attempt_for_identity(&state.db, &identity.id).await? {
            Some(attempt) if attempt.is_pending() => (
                attempt.id,
                attempt.user_code,
                parse_sqlite_datetime(&attempt.user_code_expires_at),
            ),
            _ => {
                let attempt_id = new_claim_attempt_id();
                let user_code = generate_code();
                let expiry = Utc::now()
                    + Duration::seconds(state.config.agent_auth.user_code_ttl_secs as i64);
                insert_agent_claim_attempt(
                    &state.db,
                    &NewAgentClaimAttempt {
                        id: &attempt_id,
                        identity_id: &identity.id,
                        user_code: &user_code,
                        user_code_expires_at: &to_sqlite_datetime(&expiry),
                        email: req.email.as_deref().or(identity.email.as_deref()),
                    },
                )
                .await?;
                (attempt_id, user_code, expiry)
            }
        };

    let expires_in = (expiry - Utc::now()).num_seconds().max(0);
    let body = ClaimInitiateResponse {
        registration_id: identity.id,
        claim_attempt_id: attempt_id,
        status: "initiated",
        expires_at: expiry.to_rfc3339_opts(SecondsFormat::Millis, true),
        claim_attempt: ClaimAttemptBlock {
            user_code,
            expires_in,
            verification_uri: verification_uri(&state.config.agent_auth, &state.config.public_url),
            interval: POLL_INTERVAL_SECS,
        },
    };
    Ok((StatusCode::OK, Json(body)).into_response())
}

// ── POST /agent/identity/claim/confirm (confirm) ──────────────────────────────

#[derive(Debug, Deserialize)]
pub struct ClaimConfirmRequest {
    pub user_code: Option<String>,
    /// Optional cross-check: when present, must name the registration this `user_code` belongs to.
    #[serde(default)]
    pub registration_id: Option<String>,
}

#[derive(Debug, Serialize)]
struct ClaimConfirmResponse {
    registration_id: String,
    status: &'static str,
    did: String,
}

/// `POST /agent/identity/claim/confirm` — the account owner confirms a claim (full-access authed).
pub async fn post_agent_claim_confirm(
    user: AuthenticatedUser,
    State(state): State<AppState>,
    Json(req): Json<ClaimConfirmRequest>,
) -> Response {
    match confirm(user, &state, &req).await {
        Ok(response) => response,
        Err(err) => err.into_response(),
    }
}

async fn confirm(
    user: AuthenticatedUser,
    state: &AppState,
    req: &ClaimConfirmRequest,
) -> Result<Response, AgentAuthError> {
    // Only the account holder's own full-access credential may confirm. App-password tokens
    // (narrower scope) are refused by the scope check; agent-derived tokens map to `Access` for
    // coarse admission, so `is_agent` closes the gap — an agent must never confirm itself.
    if user.scope != AuthScope::Access {
        return Err(AgentAuthError::new(
            StatusCode::UNAUTHORIZED,
            "invalid_token",
            "a full-access token is required to confirm an agent claim",
        ));
    }
    if user.is_agent() {
        return Err(AgentAuthError::new(
            StatusCode::FORBIDDEN,
            "access_denied",
            "agent-derived credentials cannot confirm a claim",
        ));
    }

    let user_code = req
        .user_code
        .as_deref()
        .filter(|s| !s.is_empty())
        .ok_or_else(|| {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_request",
                "missing required field: user_code",
            )
        })?;

    // Brute-forcing the `user_code` is bounded today by the global per-IP rate limiter, and this
    // endpoint is already full-access authenticated — so the guessing surface is an *authenticated*
    // caller racing a ~36^6-wide code within its short TTL (and success only lets them bind an
    // ownerless anonymous registration to their own account, not take over a victim's). A dedicated
    // per-code failure lockout is intentionally left to the follow-on wallet agent-consent/audit
    // hardening work, which owns claim rate-limiting — consistent with the sibling short-code
    // surface `/v1/transfer/accept`, which likewise relies on the shared limiter.
    let attempt = get_agent_claim_attempt_by_user_code(&state.db, user_code)
        .await?
        .ok_or_else(|| {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_user_code",
                "the user code is unknown",
            )
        })?;
    if !attempt.is_pending() {
        // An already-consumed attempt is `claimed_or_in_flight`; anything else non-pending (swept
        // expired, or pending-but-past-expiry) is a lapsed code.
        return Err(if attempt.status == ClaimAttemptStatus::Completed {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "claimed_or_in_flight",
                "this user code has already been used",
            )
        } else {
            AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "claim_expired",
                "the user code has expired; restart the claim",
            )
        });
    }

    let identity = get_agent_identity(&state.db, &attempt.identity_id)
        .await?
        .ok_or_else(AgentAuthError::server_error)?;

    if let Some(req_reg) = req.registration_id.as_deref().filter(|s| !s.is_empty()) {
        if req_reg != identity.id {
            return Err(AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "invalid_request",
                "registration_id does not match this user code",
            ));
        }
    }

    match identity.status {
        AgentIdentityStatus::Claimed => {
            return Err(AgentAuthError::new(
                StatusCode::BAD_REQUEST,
                "claimed_or_in_flight",
                "this registration has already been claimed",
            ));
        }
        AgentIdentityStatus::Revoked => {
            return Err(AgentAuthError::new(
                StatusCode::FORBIDDEN,
                "access_denied",
                "this agent identity has been revoked",
            ));
        }
        AgentIdentityStatus::Active => {}
    }

    // Authorization. A registration already bound to an owner (service_auth / identity_assertion)
    // may be confirmed only by that owner. An ownerless anonymous registration is bound to whoever
    // completes the ceremony — the `user_code` they were shown is the authorization.
    let bind_did = match identity.did.as_deref() {
        Some(bound) => {
            if bound != user.did {
                return Err(AgentAuthError::new(
                    StatusCode::FORBIDDEN,
                    "access_denied",
                    "this claim is bound to a different account",
                ));
            }
            None
        }
        None => Some(user.did.as_str()),
    };

    // The post-claim assertion carries the operator's current full granted-scope profile. Normalize
    // it into a deterministic, deduplicated set so this mint matches the `identity_assertion` mint
    // path byte-for-byte: `intersect_scope_tokens(xs, xs)` is the crate's canonicalizer — it returns
    // the tokens of `xs` sorted and deduped (a self-intersection, since every token is in both
    // operands). There is no separate infallible canonicalizer helper; `canonicalize_agent_scopes`
    // is the fallible startup validator, not this hot path.
    let granted = &state.config.agent_auth.granted_scopes;
    let scopes = intersect_scope_tokens(granted, granted);
    let minted = mint_identity_assertion(
        &state.oauth_signing_keypair,
        &state.config.public_url,
        state.config.agent_auth.assertion_ttl_secs,
        &user.did,
        &identity.id,
        identity.registration_type.as_str(),
        &scopes,
    )?;
    let scopes_json = scopes_to_json(&scopes);

    // One transaction: consume the pending attempt, then claim the identity. Each write carries its
    // own guard (`status = 'pending'` / `status = 'active'`), so a lost race rolls back cleanly
    // rather than double-claiming. Every read (and the pure mint) ran before `begin()` — the
    // single-connection pool cannot serve a `&SqlitePool` read while a transaction holds the
    // connection.
    let mut tx = state.db.begin().await.map_err(|e| {
        tracing::error!(error = %e, "failed to open transaction for agent claim confirm");
        AgentAuthError::server_error()
    })?;
    if !complete_agent_claim_attempt(&mut *tx, &attempt.id).await? {
        return Err(AgentAuthError::new(
            StatusCode::CONFLICT,
            "claimed_or_in_flight",
            "this claim attempt is no longer pending",
        ));
    }
    if !claim_agent_identity(
        &mut *tx,
        &identity.id,
        bind_did,
        &scopes_json,
        &minted.jwt,
        &minted.expires_sqlite,
    )
    .await?
    {
        return Err(AgentAuthError::new(
            StatusCode::CONFLICT,
            "claimed_or_in_flight",
            "this registration is no longer active",
        ));
    }
    tx.commit().await.map_err(|e| {
        tracing::error!(error = %e, "failed to commit agent claim confirm");
        AgentAuthError::server_error()
    })?;

    Ok((
        StatusCode::OK,
        Json(ClaimConfirmResponse {
            registration_id: identity.id,
            status: "claimed",
            did: user.did,
        }),
    )
        .into_response())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;

    use axum::body::Body;
    use axum::http::Request;
    use common::AgentAuthConfig;
    use serde_json::{json, Value};
    use sqlx::SqlitePool;
    use tower::ServiceExt;

    use crate::app::{app, test_state, AppState};

    // ── harness ──────────────────────────────────────────────────────────────

    async fn state_with(agent_auth: AgentAuthConfig) -> AppState {
        let base = test_state().await;
        let mut config = (*base.config).clone();
        config.agent_auth = agent_auth;
        AppState {
            config: Arc::new(config),
            ..base
        }
    }

    async fn insert_account(db: &SqlitePool, did: &str, email: &str) {
        sqlx::query(
            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
             VALUES (?, ?, 'hash', datetime('now'), datetime('now'))",
        )
        .bind(did)
        .bind(email)
        .execute(db)
        .await
        .unwrap();
    }

    /// Mint a full-access HS256 access token for `did` (the shape the extractor accepts, mirroring
    /// `auth::mod` test helpers). `scope` selects full access vs app-pass.
    fn access_token(state: &AppState, did: &str, scope: &str) -> String {
        #[derive(serde::Serialize)]
        struct Claims {
            sub: String,
            aud: String,
            exp: u64,
            scope: String,
        }
        let exp = (Utc::now().timestamp() + 3600) as u64;
        let claims = Claims {
            sub: did.to_string(),
            aud: "did:plc:test".to_string(),
            exp,
            scope: scope.to_string(),
        };
        jsonwebtoken::encode(
            &jsonwebtoken::Header::new(jsonwebtoken::Algorithm::HS256),
            &claims,
            &jsonwebtoken::EncodingKey::from_secret(&state.jwt_secret),
        )
        .unwrap()
    }

    async fn post_json(
        state: AppState,
        uri: &str,
        body: Value,
        token: Option<&str>,
    ) -> (StatusCode, Value) {
        let mut builder = Request::builder()
            .method("POST")
            .uri(uri)
            .header("content-type", "application/json");
        if let Some(t) = token {
            builder = builder.header("Authorization", format!("Bearer {t}"));
        }
        let response = app(state)
            .oneshot(builder.body(Body::from(body.to_string())).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
            .await
            .unwrap();
        let json = serde_json::from_slice(&bytes).unwrap_or(Value::Null);
        (status, json)
    }

    async fn register(state: AppState, body: Value) -> Value {
        let (_status, json) = post_json(state, "/agent/identity", body, None).await;
        json
    }

    fn anonymous_cfg() -> AgentAuthConfig {
        AgentAuthConfig {
            anonymous_enabled: true,
            ..AgentAuthConfig::default()
        }
    }

    fn service_auth_cfg() -> AgentAuthConfig {
        AgentAuthConfig {
            service_auth_enabled: true,
            ..AgentAuthConfig::default()
        }
    }

    // ── initiate ─────────────────────────────────────────────────────────────

    #[tokio::test]
    async fn anonymous_claim_token_mints_first_user_code() {
        let state = state_with(anonymous_cfg()).await;
        let reg = register(state.clone(), json!({ "type": "anonymous" })).await;
        let claim_token = reg["claim_token"].as_str().unwrap().to_string();
        let registration_id = reg["registration_id"].as_str().unwrap().to_string();

        let (status, body) = post_json(
            state.clone(),
            "/agent/identity/claim",
            json!({ "claim_token": claim_token }),
            None,
        )
        .await;

        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["status"], "initiated");
        assert_eq!(body["registration_id"], registration_id);
        assert!(body["claim_attempt_id"]
            .as_str()
            .unwrap()
            .starts_with("cla_"));
        assert_eq!(
            body["claim_attempt"]["user_code"].as_str().unwrap().len(),
            6
        );
        assert_eq!(body["claim_attempt"]["interval"], 5);
        assert_eq!(
            body["claim_attempt"]["verification_uri"],
            "https://test.example.com/agent/claim"
        );
        // Exactly one pending attempt now exists for this identity.
        let attempts: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM agent_claim_attempts WHERE identity_id = ?")
                .bind(&registration_id)
                .fetch_one(&state.db)
                .await
                .unwrap();
        assert_eq!(attempts, 1);
    }

    #[tokio::test]
    async fn service_auth_claim_reuses_pending_user_code() {
        let state = state_with(service_auth_cfg()).await;
        insert_account(&state.db, "did:plc:svcclaim1111111111", "agent@example.com").await;
        let reg = register(
            state.clone(),
            json!({ "type": "service_auth", "login_hint": "agent@example.com" }),
        )
        .await;
        let claim_token = reg["claim_token"].as_str().unwrap().to_string();
        // Registration already minted a user_code; re-initiating must return the SAME one.
        let original_code = reg["claim"]["user_code"].as_str().unwrap().to_string();

        let (status, body) = post_json(
            state.clone(),
            "/agent/identity/claim",
            json!({ "claim_token": claim_token }),
            None,
        )
        .await;

        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["claim_attempt"]["user_code"], original_code);
        // No second attempt was created.
        let attempts: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM agent_claim_attempts")
            .fetch_one(&state.db)
            .await
            .unwrap();
        assert_eq!(attempts, 1);
    }

    #[tokio::test]
    async fn missing_claim_token_is_invalid_request() {
        let state = state_with(anonymous_cfg()).await;
        let (status, body) = post_json(state, "/agent/identity/claim", json!({}), None).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "invalid_request");
    }

    #[tokio::test]
    async fn unknown_claim_token_is_invalid_claim_token() {
        let state = state_with(anonymous_cfg()).await;
        let (status, body) = post_json(
            state,
            "/agent/identity/claim",
            json!({ "claim_token": "clm_nope" }),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "invalid_claim_token");
    }

    #[tokio::test]
    async fn expired_claim_token_is_claim_expired() {
        let state = state_with(anonymous_cfg()).await;
        // Seed an active anonymous identity whose claim token expired in the past.
        sqlx::query(
            "INSERT INTO agent_identities \
             (id, did, registration_type, scopes, assertion_expires_at, claim_token, \
              claim_token_expires_at, status, created_at, updated_at) \
             VALUES ('reg_exp', NULL, 'anonymous', '[]', datetime('now', '+1 hour'), \
                     'clm_expired', datetime('now', '-1 minute'), 'active', datetime('now'), \
                     datetime('now'))",
        )
        .execute(&state.db)
        .await
        .unwrap();

        let (status, body) = post_json(
            state,
            "/agent/identity/claim",
            json!({ "claim_token": "clm_expired" }),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "claim_expired");
    }

    #[tokio::test]
    async fn already_claimed_is_claimed_or_in_flight() {
        let state = state_with(anonymous_cfg()).await;
        insert_account(&state.db, "did:plc:claimeddid1111111", "u@example.com").await;
        sqlx::query(
            "INSERT INTO agent_identities \
             (id, did, registration_type, scopes, assertion_expires_at, claim_token, \
              claim_token_expires_at, status, created_at, updated_at) \
             VALUES ('reg_done', 'did:plc:claimeddid1111111', 'anonymous', '[]', \
                     datetime('now', '+1 hour'), 'clm_done', datetime('now', '+1 hour'), \
                     'claimed', datetime('now'), datetime('now'))",
        )
        .execute(&state.db)
        .await
        .unwrap();

        let (status, body) = post_json(
            state,
            "/agent/identity/claim",
            json!({ "claim_token": "clm_done" }),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "claimed_or_in_flight");
    }

    // ── confirm ──────────────────────────────────────────────────────────────

    /// Register anonymously, initiate the ceremony, and return `(user_code, registration_id)`.
    async fn anonymous_ceremony(state: &AppState) -> (String, String) {
        let reg = register(state.clone(), json!({ "type": "anonymous" })).await;
        let claim_token = reg["claim_token"].as_str().unwrap().to_string();
        let registration_id = reg["registration_id"].as_str().unwrap().to_string();
        let (_s, body) = post_json(
            state.clone(),
            "/agent/identity/claim",
            json!({ "claim_token": claim_token }),
            None,
        )
        .await;
        let user_code = body["claim_attempt"]["user_code"]
            .as_str()
            .unwrap()
            .to_string();
        (user_code, registration_id)
    }

    #[tokio::test]
    async fn confirm_binds_anonymous_owner_and_enables_exchange() {
        let state = state_with(anonymous_cfg()).await;
        let did = "did:plc:anonowner111111111";
        insert_account(&state.db, did, "owner@example.com").await;
        let (user_code, registration_id) = anonymous_ceremony(&state).await;
        let token = access_token(&state, did, "com.atproto.access");

        let (status, body) = post_json(
            state.clone(),
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            Some(&token),
        )
        .await;

        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["status"], "claimed");
        assert_eq!(body["did"], did);

        // The identity is now claimed, bound to the owner, with a fresh assertion stored.
        let row: (Option<String>, String, Option<String>) = sqlx::query_as(
            "SELECT did, status, identity_assertion FROM agent_identities WHERE id = ?",
        )
        .bind(&registration_id)
        .fetch_one(&state.db)
        .await
        .unwrap();
        assert_eq!(row.0.as_deref(), Some(did));
        assert_eq!(row.1, "claimed");
        let stored_assertion = row.2.expect("post-claim assertion stored");

        // End-to-end: the stored post-claim assertion now exchanges at the token endpoint.
        let (tstatus, tbody) = post_form(
            state,
            "/oauth/token",
            &format!(
                "grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion={stored_assertion}"
            ),
        )
        .await;
        assert_eq!(
            tstatus,
            StatusCode::OK,
            "post-claim assertion must exchange"
        );
        assert_eq!(tbody["token_type"], "Bearer");
        assert!(tbody["access_token"].as_str().unwrap().split('.').count() == 3);
    }

    async fn post_form(state: AppState, uri: &str, body: &str) -> (StatusCode, Value) {
        let response = app(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(uri)
                    .header("content-type", "application/x-www-form-urlencoded")
                    .body(Body::from(body.to_string()))
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), 1 << 20)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(Value::Null),
        )
    }

    #[tokio::test]
    async fn confirm_service_auth_binding_succeeds() {
        let state = state_with(service_auth_cfg()).await;
        let did = "did:plc:svcowner1111111111";
        insert_account(&state.db, did, "svc@example.com").await;
        let reg = register(
            state.clone(),
            json!({ "type": "service_auth", "login_hint": "svc@example.com" }),
        )
        .await;
        let user_code = reg["claim"]["user_code"].as_str().unwrap().to_string();
        let token = access_token(&state, did, "com.atproto.access");

        let (status, body) = post_json(
            state,
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            Some(&token),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["status"], "claimed");
        assert_eq!(body["did"], did);
    }

    #[tokio::test]
    async fn confirm_by_wrong_account_is_access_denied() {
        let state = state_with(service_auth_cfg()).await;
        let owner = "did:plc:rightowner111111111";
        let intruder = "did:plc:wrongowner111111111";
        insert_account(&state.db, owner, "right@example.com").await;
        insert_account(&state.db, intruder, "wrong@example.com").await;
        let reg = register(
            state.clone(),
            json!({ "type": "service_auth", "login_hint": "right@example.com" }),
        )
        .await;
        let user_code = reg["claim"]["user_code"].as_str().unwrap().to_string();
        // The intruder holds a valid full-access token, but for the wrong account.
        let token = access_token(&state, intruder, "com.atproto.access");

        let (status, body) = post_json(
            state.clone(),
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            Some(&token),
        )
        .await;
        assert_eq!(status, StatusCode::FORBIDDEN);
        assert_eq!(body["error"], "access_denied");
        // Nothing was claimed.
        let claimed: i64 =
            sqlx::query_scalar("SELECT COUNT(*) FROM agent_identities WHERE status = 'claimed'")
                .fetch_one(&state.db)
                .await
                .unwrap();
        assert_eq!(claimed, 0);
    }

    #[tokio::test]
    async fn confirm_unknown_user_code_is_invalid() {
        let state = state_with(anonymous_cfg()).await;
        let did = "did:plc:nocode11111111111";
        insert_account(&state.db, did, "n@example.com").await;
        let token = access_token(&state, did, "com.atproto.access");
        let (status, body) = post_json(
            state,
            "/agent/identity/claim/confirm",
            json!({ "user_code": "ZZZZZZ" }),
            Some(&token),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "invalid_user_code");
    }

    #[tokio::test]
    async fn confirm_second_time_is_claimed_or_in_flight() {
        let state = state_with(anonymous_cfg()).await;
        let did = "did:plc:twice1111111111111";
        insert_account(&state.db, did, "t@example.com").await;
        let (user_code, _reg) = anonymous_ceremony(&state).await;
        let token = access_token(&state, did, "com.atproto.access");

        let (first, _) = post_json(
            state.clone(),
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code.clone() }),
            Some(&token),
        )
        .await;
        assert_eq!(first, StatusCode::OK);

        let (second, body) = post_json(
            state,
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            Some(&token),
        )
        .await;
        assert_eq!(second, StatusCode::BAD_REQUEST);
        assert_eq!(body["error"], "claimed_or_in_flight");
    }

    #[tokio::test]
    async fn confirm_app_password_token_is_refused() {
        let state = state_with(anonymous_cfg()).await;
        let did = "did:plc:apppass1111111111";
        insert_account(&state.db, did, "a@example.com").await;
        let (user_code, _reg) = anonymous_ceremony(&state).await;
        // App-password scope is narrower than full access → refused before any lookup.
        let token = access_token(&state, did, "com.atproto.appPass");

        let (status, body) = post_json(
            state,
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            Some(&token),
        )
        .await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);
        assert_eq!(body["error"], "invalid_token");
    }

    #[tokio::test]
    async fn confirm_without_auth_is_unauthorized() {
        let state = state_with(anonymous_cfg()).await;
        let (user_code, _reg) = anonymous_ceremony(&state).await;
        let (status, _body) = post_json(
            state,
            "/agent/identity/claim/confirm",
            json!({ "user_code": user_code }),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::UNAUTHORIZED);
    }
}

// pattern: Imperative Shell
//
// auth.md agent-registration queries. Reads and writes the `agent_identities` and
// `agent_claim_attempts` tables (V037); returns plain data structs. No JWT validation,
// code generation, or route-level state-machine decisions live here.

#![allow(dead_code)]

use common::{ApiError, ErrorCode};
use sqlx::Sqlite;

use super::is_unique_violation;

type IdentitySqlRow = (
    String,
    Option<String>,
    String,
    Option<String>,
    Option<String>,
    Option<String>,
    String,
    Option<String>,
    String,
    Option<String>,
    Option<String>,
    Option<String>,
    String,
    String,
    String,
);

type ClaimAttemptSqlRow = (
    String,
    String,
    String,
    String,
    Option<String>,
    String,
    String,
    bool,
);

/// Registration method recorded for an auth.md agent identity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum RegistrationType {
    IdentityAssertion,
    ServiceAuth,
    Anonymous,
}

impl RegistrationType {
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            RegistrationType::IdentityAssertion => "identity_assertion",
            RegistrationType::ServiceAuth => "service_auth",
            RegistrationType::Anonymous => "anonymous",
        }
    }

    fn from_string(value: String) -> Self {
        match value.as_str() {
            "identity_assertion" => RegistrationType::IdentityAssertion,
            "service_auth" => RegistrationType::ServiceAuth,
            "anonymous" => RegistrationType::Anonymous,
            _ => RegistrationType::Anonymous,
        }
    }
}

/// Durable lifecycle status for an agent identity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum AgentIdentityStatus {
    Active,
    Claimed,
    Revoked,
}

impl AgentIdentityStatus {
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            AgentIdentityStatus::Active => "active",
            AgentIdentityStatus::Claimed => "claimed",
            AgentIdentityStatus::Revoked => "revoked",
        }
    }

    fn from_string(value: String) -> Self {
        match value.as_str() {
            "active" => AgentIdentityStatus::Active,
            "claimed" => AgentIdentityStatus::Claimed,
            "revoked" => AgentIdentityStatus::Revoked,
            _ => AgentIdentityStatus::Revoked,
        }
    }
}

/// Durable lifecycle status for a user-code claim ceremony attempt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum ClaimAttemptStatus {
    Pending,
    Completed,
    Expired,
}

impl ClaimAttemptStatus {
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            ClaimAttemptStatus::Pending => "pending",
            ClaimAttemptStatus::Completed => "completed",
            ClaimAttemptStatus::Expired => "expired",
        }
    }

    fn from_string(value: String) -> Self {
        match value.as_str() {
            "pending" => ClaimAttemptStatus::Pending,
            "completed" => ClaimAttemptStatus::Completed,
            "expired" => ClaimAttemptStatus::Expired,
            _ => ClaimAttemptStatus::Expired,
        }
    }
}

/// Full agent identity row. Scope fields are stored as JSON array strings; route code owns
/// parsing/validation because it knows the applicable grant flow and permission grammar.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AgentIdentityRow {
    pub(crate) id: String,
    /// The owning account DID, or `None` for an unclaimed `anonymous` registration (V038): an
    /// anonymous identity has no owning account until a later claim ceremony binds one.
    pub(crate) did: Option<String>,
    pub(crate) registration_type: RegistrationType,
    pub(crate) issuer: Option<String>,
    pub(crate) subject: Option<String>,
    pub(crate) email: Option<String>,
    pub(crate) scopes: String,
    pub(crate) identity_assertion: Option<String>,
    pub(crate) assertion_expires_at: String,
    pub(crate) pre_claim_scopes: Option<String>,
    pub(crate) claim_token: Option<String>,
    pub(crate) claim_token_expires_at: Option<String>,
    pub(crate) status: AgentIdentityStatus,
    pub(crate) created_at: String,
    pub(crate) updated_at: String,
}

/// Fields needed to insert an agent identity. IDs/tokens/assertions are generated by callers.
pub(crate) struct NewAgentIdentity<'a> {
    pub(crate) id: &'a str,
    /// The owning account DID, or `None` for an unclaimed `anonymous` registration (V038).
    pub(crate) did: Option<&'a str>,
    pub(crate) registration_type: RegistrationType,
    pub(crate) issuer: Option<&'a str>,
    pub(crate) subject: Option<&'a str>,
    pub(crate) email: Option<&'a str>,
    pub(crate) scopes: &'a str,
    pub(crate) identity_assertion: Option<&'a str>,
    pub(crate) assertion_expires_at: &'a str,
    pub(crate) pre_claim_scopes: Option<&'a str>,
    pub(crate) claim_token: Option<&'a str>,
    pub(crate) claim_token_expires_at: Option<&'a str>,
}

/// Result of inserting an agent identity.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum InsertAgentIdentityOutcome {
    Created,
    /// Primary-key or `(issuer, subject)` uniqueness collision.
    Duplicate,
}

/// Claim ceremony row with expiry derived at query time.
#[derive(Debug, Clone, PartialEq, Eq)]
pub(crate) struct AgentClaimAttemptRow {
    pub(crate) id: String,
    pub(crate) identity_id: String,
    pub(crate) user_code: String,
    pub(crate) user_code_expires_at: String,
    pub(crate) email: Option<String>,
    pub(crate) status: ClaimAttemptStatus,
    pub(crate) created_at: String,
    /// Derived: `datetime(user_code_expires_at) <= datetime('now')` at query time.
    pub(crate) is_expired: bool,
}

impl AgentClaimAttemptRow {
    /// A claim attempt can be completed only while pending and unexpired.
    pub(crate) fn is_pending(&self) -> bool {
        self.status == ClaimAttemptStatus::Pending && !self.is_expired
    }
}

/// Fields needed to insert a user-code claim attempt.
pub(crate) struct NewAgentClaimAttempt<'a> {
    pub(crate) id: &'a str,
    pub(crate) identity_id: &'a str,
    pub(crate) user_code: &'a str,
    pub(crate) user_code_expires_at: &'a str,
    pub(crate) email: Option<&'a str>,
}

/// Insert a new agent identity row. Generic over the executor so future route code can
/// compose registration and claim-attempt writes inside one transaction.
pub(crate) async fn insert_agent_identity<'e, E>(
    executor: E,
    identity: &NewAgentIdentity<'_>,
) -> Result<InsertAgentIdentityOutcome, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "INSERT INTO agent_identities \
         (id, did, registration_type, issuer, subject, email, scopes, identity_assertion, \
          assertion_expires_at, pre_claim_scopes, claim_token, claim_token_expires_at, \
          created_at, updated_at) \
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))",
    )
    .bind(identity.id)
    .bind(identity.did)
    .bind(identity.registration_type.as_str())
    .bind(identity.issuer)
    .bind(identity.subject)
    .bind(identity.email)
    .bind(identity.scopes)
    .bind(identity.identity_assertion)
    .bind(identity.assertion_expires_at)
    .bind(identity.pre_claim_scopes)
    .bind(identity.claim_token)
    .bind(identity.claim_token_expires_at)
    .execute(executor)
    .await;

    match result {
        Ok(_) => Ok(InsertAgentIdentityOutcome::Created),
        Err(e) if is_unique_violation(&e) => Ok(InsertAgentIdentityOutcome::Duplicate),
        Err(e) => {
            tracing::error!(identity_id = %identity.id, error = %e, "DB error inserting agent identity");
            Err(ApiError::new(
                ErrorCode::InternalError,
                "failed to create agent identity",
            ))
        }
    }
}

/// Fetch an agent identity by registration id.
pub(crate) async fn get_agent_identity(
    db: &sqlx::SqlitePool,
    id: &str,
) -> Result<Option<AgentIdentityRow>, ApiError> {
    fetch_identity_by(db, "id", id).await
}

/// Fetch an agent identity by one-time claim token.
pub(crate) async fn get_agent_identity_by_claim_token(
    db: &sqlx::SqlitePool,
    claim_token: &str,
) -> Result<Option<AgentIdentityRow>, ApiError> {
    fetch_identity_by(db, "claim_token", claim_token).await
}

/// Fetch an agent identity by its `(issuer, subject)` pair.
///
/// Backs the `identity_assertion` flow: an ID-JAG's `(iss, sub)` is the stable key for an agent's
/// registration, deduplicated by the partial unique index `idx_agent_identities_iss_sub`.
pub(crate) async fn get_agent_identity_by_issuer_subject(
    db: &sqlx::SqlitePool,
    issuer: &str,
    subject: &str,
) -> Result<Option<AgentIdentityRow>, ApiError> {
    let row = sqlx::query_as::<_, IdentitySqlRow>(
        "SELECT id, did, registration_type, issuer, subject, email, scopes, identity_assertion, \
                assertion_expires_at, pre_claim_scopes, claim_token, claim_token_expires_at, \
                status, created_at, updated_at \
         FROM agent_identities WHERE issuer = ? AND subject = ?",
    )
    .bind(issuer)
    .bind(subject)
    .fetch_optional(db)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "DB error fetching agent identity by issuer/subject");
        ApiError::new(ErrorCode::InternalError, "failed to load agent identity")
    })?;
    Ok(row.map(into_identity_row))
}

async fn fetch_identity_by(
    db: &sqlx::SqlitePool,
    column: &str,
    value: &str,
) -> Result<Option<AgentIdentityRow>, ApiError> {
    let sql = match column {
        "id" => {
            "SELECT id, did, registration_type, issuer, subject, email, scopes, identity_assertion, \
                    assertion_expires_at, pre_claim_scopes, claim_token, claim_token_expires_at, \
                    status, created_at, updated_at \
             FROM agent_identities WHERE id = ?"
        }
        "claim_token" => {
            "SELECT id, did, registration_type, issuer, subject, email, scopes, identity_assertion, \
                    assertion_expires_at, pre_claim_scopes, claim_token, claim_token_expires_at, \
                    status, created_at, updated_at \
             FROM agent_identities WHERE claim_token = ?"
        }
        _ => unreachable!("unsupported agent identity lookup column"),
    };

    let row = sqlx::query_as::<_, IdentitySqlRow>(sql)
    .bind(value)
    .fetch_optional(db)
    .await
    .map_err(|e| {
        tracing::error!(lookup_column = %column, error = %e, "DB error fetching agent identity");
        ApiError::new(ErrorCode::InternalError, "failed to load agent identity")
    })?;

    Ok(row.map(into_identity_row))
}

/// Update identity status. Used by claim completion and revocation flows.
pub(crate) async fn set_agent_identity_status<'e, E>(
    executor: E,
    id: &str,
    status: AgentIdentityStatus,
) -> Result<bool, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "UPDATE agent_identities SET status = ?, updated_at = datetime('now') WHERE id = ?",
    )
    .bind(status.as_str())
    .bind(id)
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(identity_id = %id, error = %e, "DB error updating agent identity status");
        ApiError::new(ErrorCode::InternalError, "failed to update agent identity")
    })?;
    Ok(result.rows_affected() == 1)
}

/// Store a freshly minted service assertion for an identity.
pub(crate) async fn set_agent_identity_assertion<'e, E>(
    executor: E,
    id: &str,
    identity_assertion: &str,
    assertion_expires_at: &str,
) -> Result<bool, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "UPDATE agent_identities \
         SET identity_assertion = ?, assertion_expires_at = ?, updated_at = datetime('now') \
         WHERE id = ?",
    )
    .bind(identity_assertion)
    .bind(assertion_expires_at)
    .bind(id)
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(identity_id = %id, error = %e, "DB error updating agent identity assertion");
        ApiError::new(ErrorCode::InternalError, "failed to update agent identity")
    })?;
    Ok(result.rows_affected() == 1)
}

/// Atomically claim an `active` agent identity: bind an owning DID (for a previously ownerless
/// `anonymous` registration), store the freshly minted post-claim assertion and its granted scopes,
/// and flip the status to `claimed` — all in one single-table UPDATE.
///
/// `bind_did` is `Some(did)` only for the `anonymous` flow (whose `did` was NULL); pass `None` for a
/// registration already bound at registration time (`service_auth` / `identity_assertion`), where
/// `COALESCE(NULL, did)` leaves the existing owner untouched. The `status = 'active'` guard makes the
/// claim idempotent-safe: a concurrent or repeat confirmation of an already-`claimed`/`revoked`
/// identity affects no rows and returns `false`.
///
/// The `(? IS NULL OR did IS NULL)` guard is defense in depth: a DID can be *bound* only when the
/// row is currently ownerless, so even a future caller that mistakenly passed `Some(did)` for an
/// already-owned registration could never hijack its owner (the UPDATE would simply match no rows).
/// Scope/assertion fields still update in the `bind_did = None` (already-owned) path.
pub(crate) async fn claim_agent_identity<'e, E>(
    executor: E,
    id: &str,
    bind_did: Option<&str>,
    scopes: &str,
    identity_assertion: &str,
    assertion_expires_at: &str,
) -> Result<bool, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "UPDATE agent_identities \
         SET status = 'claimed', \
             did = COALESCE(?, did), \
             scopes = ?, \
             identity_assertion = ?, \
             assertion_expires_at = ?, \
             updated_at = datetime('now') \
         WHERE id = ? AND status = 'active' AND (? IS NULL OR did IS NULL)",
    )
    .bind(bind_did)
    .bind(scopes)
    .bind(identity_assertion)
    .bind(assertion_expires_at)
    .bind(id)
    .bind(bind_did)
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(identity_id = %id, error = %e, "DB error claiming agent identity");
        ApiError::new(ErrorCode::InternalError, "failed to claim agent identity")
    })?;
    Ok(result.rows_affected() == 1)
}

/// Insert a new claim ceremony attempt.
pub(crate) async fn insert_agent_claim_attempt<'e, E>(
    executor: E,
    attempt: &NewAgentClaimAttempt<'_>,
) -> Result<(), ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    sqlx::query(
        "INSERT INTO agent_claim_attempts \
         (id, identity_id, user_code, user_code_expires_at, email, created_at) \
         VALUES (?, ?, ?, ?, ?, datetime('now'))",
    )
    .bind(attempt.id)
    .bind(attempt.identity_id)
    .bind(attempt.user_code)
    .bind(attempt.user_code_expires_at)
    .bind(attempt.email)
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(attempt_id = %attempt.id, identity_id = %attempt.identity_id, error = %e, "DB error inserting agent claim attempt");
        ApiError::new(
            ErrorCode::InternalError,
            "failed to create agent claim attempt",
        )
    })?;
    Ok(())
}

/// Fetch a claim attempt by its user-facing code.
pub(crate) async fn get_agent_claim_attempt_by_user_code(
    db: &sqlx::SqlitePool,
    user_code: &str,
) -> Result<Option<AgentClaimAttemptRow>, ApiError> {
    let row = sqlx::query_as::<_, ClaimAttemptSqlRow>(
        "SELECT id, identity_id, user_code, user_code_expires_at, email, status, created_at, \
                datetime(user_code_expires_at) <= datetime('now') AS is_expired \
         FROM agent_claim_attempts \
         WHERE user_code = ?",
    )
    .bind(user_code)
    .fetch_optional(db)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "DB error fetching agent claim attempt by user code");
        ApiError::new(ErrorCode::InternalError, "failed to load claim attempt")
    })?;
    Ok(row.map(into_claim_attempt_row))
}

/// Fetch the newest claim attempt for an identity.
pub(crate) async fn latest_agent_claim_attempt_for_identity(
    db: &sqlx::SqlitePool,
    identity_id: &str,
) -> Result<Option<AgentClaimAttemptRow>, ApiError> {
    let row = sqlx::query_as::<_, ClaimAttemptSqlRow>(
        "SELECT id, identity_id, user_code, user_code_expires_at, email, status, created_at, \
                datetime(user_code_expires_at) <= datetime('now') AS is_expired \
         FROM agent_claim_attempts \
         WHERE identity_id = ? ORDER BY created_at DESC, id DESC LIMIT 1",
    )
    .bind(identity_id)
    .fetch_optional(db)
    .await
    .map_err(|e| {
        tracing::error!(identity_id = %identity_id, error = %e, "DB error fetching latest agent claim attempt");
        ApiError::new(ErrorCode::InternalError, "failed to load claim attempt")
    })?;
    Ok(row.map(into_claim_attempt_row))
}

/// Atomically complete a pending, unexpired claim attempt.
pub(crate) async fn complete_agent_claim_attempt<'e, E>(
    executor: E,
    id: &str,
) -> Result<bool, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "UPDATE agent_claim_attempts SET status = 'completed' \
         WHERE id = ? AND status = 'pending' AND datetime(user_code_expires_at) > datetime('now')",
    )
    .bind(id)
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(attempt_id = %id, error = %e, "DB error completing agent claim attempt");
        ApiError::new(ErrorCode::InternalError, "failed to complete claim attempt")
    })?;
    Ok(result.rows_affected() == 1)
}

/// Mark any expired pending attempts as expired. Returns the number of affected rows.
pub(crate) async fn expire_pending_agent_claim_attempts<'e, E>(executor: E) -> Result<u64, ApiError>
where
    E: sqlx::Executor<'e, Database = Sqlite>,
{
    let result = sqlx::query(
        "UPDATE agent_claim_attempts SET status = 'expired' \
         WHERE status = 'pending' AND datetime(user_code_expires_at) <= datetime('now')",
    )
    .execute(executor)
    .await
    .map_err(|e| {
        tracing::error!(error = %e, "DB error expiring agent claim attempts");
        ApiError::new(ErrorCode::InternalError, "failed to expire claim attempts")
    })?;
    Ok(result.rows_affected())
}

fn into_identity_row(row: IdentitySqlRow) -> AgentIdentityRow {
    let (
        id,
        did,
        registration_type,
        issuer,
        subject,
        email,
        scopes,
        identity_assertion,
        assertion_expires_at,
        pre_claim_scopes,
        claim_token,
        claim_token_expires_at,
        status,
        created_at,
        updated_at,
    ) = row;

    AgentIdentityRow {
        id,
        did,
        registration_type: RegistrationType::from_string(registration_type),
        issuer,
        subject,
        email,
        scopes,
        identity_assertion,
        assertion_expires_at,
        pre_claim_scopes,
        claim_token,
        claim_token_expires_at,
        status: AgentIdentityStatus::from_string(status),
        created_at,
        updated_at,
    }
}

fn into_claim_attempt_row(row: ClaimAttemptSqlRow) -> AgentClaimAttemptRow {
    let (id, identity_id, user_code, user_code_expires_at, email, status, created_at, is_expired) =
        row;
    AgentClaimAttemptRow {
        id,
        identity_id,
        user_code,
        user_code_expires_at,
        email,
        status: ClaimAttemptStatus::from_string(status),
        created_at,
        is_expired,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::db::{open_pool, run_migrations};

    async fn test_pool() -> sqlx::SqlitePool {
        let pool = open_pool("sqlite::memory:").await.unwrap();
        run_migrations(&pool).await.unwrap();
        pool
    }

    async fn insert_account(pool: &sqlx::SqlitePool, did: &str) {
        sqlx::query(
            "INSERT INTO accounts (did, email, password_hash, created_at, updated_at) \
             VALUES (?, ?, 'hash', datetime('now'), datetime('now'))",
        )
        .bind(did)
        .bind(format!("{}@example.com", did.replace(':', "-")))
        .execute(pool)
        .await
        .unwrap();
    }

    fn new_identity<'a>(id: &'a str, did: &'a str) -> NewAgentIdentity<'a> {
        NewAgentIdentity {
            id,
            did: Some(did),
            registration_type: RegistrationType::Anonymous,
            issuer: None,
            subject: None,
            email: None,
            scopes: r#"["com.atproto.access"]"#,
            identity_assertion: Some("assertion.jwt"),
            assertion_expires_at: "2099-01-01T00:00:00Z",
            pre_claim_scopes: Some(r#"["com.atproto.access"]"#),
            claim_token: Some("clm_test"),
            claim_token_expires_at: Some("2099-01-01T00:00:00Z"),
        }
    }

    #[tokio::test]
    async fn insert_and_fetch_identity_by_id_and_claim_token() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthowner1111111111";
        insert_account(&pool, did).await;

        let outcome = insert_agent_identity(&pool, &new_identity("reg_1", did))
            .await
            .unwrap();
        assert_eq!(outcome, InsertAgentIdentityOutcome::Created);

        let by_id = get_agent_identity(&pool, "reg_1").await.unwrap().unwrap();
        assert_eq!(by_id.id, "reg_1");
        assert_eq!(by_id.did.as_deref(), Some(did));
        assert_eq!(by_id.registration_type, RegistrationType::Anonymous);
        assert_eq!(by_id.status, AgentIdentityStatus::Active);
        assert_eq!(by_id.claim_token.as_deref(), Some("clm_test"));

        let by_claim = get_agent_identity_by_claim_token(&pool, "clm_test")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(by_claim.id, "reg_1");
    }

    #[tokio::test]
    async fn anonymous_identity_persists_without_owning_did() {
        // V038 made `did` nullable so an anonymous registration (no owning account yet) can be
        // stored. Insert one with `did: None` and read it back.
        let pool = test_pool().await;
        let anon = NewAgentIdentity {
            did: None,
            issuer: None,
            subject: None,
            ..new_identity("reg_anon", "unused")
        };
        assert_eq!(
            insert_agent_identity(&pool, &anon).await.unwrap(),
            InsertAgentIdentityOutcome::Created
        );

        let row = get_agent_identity(&pool, "reg_anon")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.did, None);
        assert_eq!(row.status, AgentIdentityStatus::Active);
        assert_eq!(row.claim_token.as_deref(), Some("clm_test"));
    }

    #[tokio::test]
    async fn duplicate_issuer_subject_reported_as_duplicate() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthowner2222222222";
        insert_account(&pool, did).await;

        let first = NewAgentIdentity {
            id: "reg_issuer_1",
            registration_type: RegistrationType::IdentityAssertion,
            issuer: Some("https://issuer.example.com"),
            subject: Some("subject-1"),
            ..new_identity("reg_issuer_1", did)
        };
        let second = NewAgentIdentity {
            id: "reg_issuer_2",
            registration_type: RegistrationType::IdentityAssertion,
            issuer: Some("https://issuer.example.com"),
            subject: Some("subject-1"),
            claim_token: Some("clm_other"),
            ..new_identity("reg_issuer_2", did)
        };

        assert_eq!(
            insert_agent_identity(&pool, &first).await.unwrap(),
            InsertAgentIdentityOutcome::Created
        );
        assert_eq!(
            insert_agent_identity(&pool, &second).await.unwrap(),
            InsertAgentIdentityOutcome::Duplicate
        );
    }

    #[tokio::test]
    async fn identity_status_and_assertion_can_be_updated() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthowner3333333333";
        insert_account(&pool, did).await;
        insert_agent_identity(&pool, &new_identity("reg_update", did))
            .await
            .unwrap();

        assert!(
            set_agent_identity_status(&pool, "reg_update", AgentIdentityStatus::Claimed)
                .await
                .unwrap()
        );
        assert!(set_agent_identity_assertion(
            &pool,
            "reg_update",
            "new.assertion.jwt",
            "2099-02-01T00:00:00Z",
        )
        .await
        .unwrap());

        let row = get_agent_identity(&pool, "reg_update")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.status, AgentIdentityStatus::Claimed);
        assert_eq!(row.identity_assertion.as_deref(), Some("new.assertion.jwt"));
        assert_eq!(row.assertion_expires_at, "2099-02-01T00:00:00Z");
    }

    #[tokio::test]
    async fn claim_attempt_lifecycle_is_atomic_and_expiry_aware() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthowner4444444444";
        insert_account(&pool, did).await;
        insert_agent_identity(&pool, &new_identity("reg_claim", did))
            .await
            .unwrap();

        insert_agent_claim_attempt(
            &pool,
            &NewAgentClaimAttempt {
                id: "cla_pending",
                identity_id: "reg_claim",
                user_code: "123456",
                user_code_expires_at: "2099-01-01T00:00:00Z",
                email: Some("user@example.com"),
            },
        )
        .await
        .unwrap();

        let attempt = get_agent_claim_attempt_by_user_code(&pool, "123456")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(attempt.id, "cla_pending");
        assert!(attempt.is_pending());

        assert!(complete_agent_claim_attempt(&pool, "cla_pending")
            .await
            .unwrap());
        assert!(!complete_agent_claim_attempt(&pool, "cla_pending")
            .await
            .unwrap());

        let latest = latest_agent_claim_attempt_for_identity(&pool, "reg_claim")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(latest.status, ClaimAttemptStatus::Completed);
        assert!(!latest.is_pending());
    }

    #[tokio::test]
    async fn expired_attempts_are_marked_and_cannot_complete() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthowner5555555555";
        insert_account(&pool, did).await;
        insert_agent_identity(&pool, &new_identity("reg_expired", did))
            .await
            .unwrap();
        insert_agent_claim_attempt(
            &pool,
            &NewAgentClaimAttempt {
                id: "cla_expired",
                identity_id: "reg_expired",
                user_code: "654321",
                user_code_expires_at: "2000-01-01T00:00:00Z",
                email: None,
            },
        )
        .await
        .unwrap();

        assert!(!complete_agent_claim_attempt(&pool, "cla_expired")
            .await
            .unwrap());
        assert_eq!(expire_pending_agent_claim_attempts(&pool).await.unwrap(), 1);

        let attempt = get_agent_claim_attempt_by_user_code(&pool, "654321")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(attempt.status, ClaimAttemptStatus::Expired);
        assert!(attempt.is_expired);
    }

    #[tokio::test]
    async fn claim_binds_owner_upgrades_assertion_and_flips_status() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthclaim1111111";
        insert_account(&pool, did).await;

        // An ownerless (anonymous) registration: did NULL, active, narrow pre-claim scopes.
        let anon = NewAgentIdentity {
            did: None,
            scopes: r#"["blob:*/*"]"#,
            pre_claim_scopes: Some(r#"["blob:*/*"]"#),
            identity_assertion: Some("pre.claim.jwt"),
            ..new_identity("reg_claimbind", "unused")
        };
        insert_agent_identity(&pool, &anon).await.unwrap();

        // The claim binds the owner, upgrades scopes + assertion, and flips to claimed.
        assert!(claim_agent_identity(
            &pool,
            "reg_claimbind",
            Some(did),
            r#"["atproto","repo:*?action=create&action=update","blob:*/*"]"#,
            "post.claim.jwt",
            "2099-03-01T00:00:00Z",
        )
        .await
        .unwrap());

        let row = get_agent_identity(&pool, "reg_claimbind")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.did.as_deref(), Some(did));
        assert_eq!(row.status, AgentIdentityStatus::Claimed);
        assert_eq!(row.identity_assertion.as_deref(), Some("post.claim.jwt"));
        assert_eq!(
            row.scopes,
            r#"["atproto","repo:*?action=create&action=update","blob:*/*"]"#
        );

        // Re-claiming an already-claimed identity is a no-op (status guard) → affects no rows.
        assert!(!claim_agent_identity(
            &pool,
            "reg_claimbind",
            Some(did),
            r#"["atproto"]"#,
            "other.jwt",
            "2099-04-01T00:00:00Z",
        )
        .await
        .unwrap());
    }

    #[tokio::test]
    async fn claim_with_no_bind_did_preserves_prebound_owner() {
        let pool = test_pool().await;
        let did = "did:plc:agentauthclaim2222222";
        insert_account(&pool, did).await;

        // A service_auth-style registration already bound to an owner at registration time.
        insert_agent_identity(&pool, &new_identity("reg_prebound", did))
            .await
            .unwrap();

        // Claiming with no bind_did: COALESCE(NULL, did) keeps the existing owner.
        assert!(claim_agent_identity(
            &pool,
            "reg_prebound",
            None,
            r#"["atproto"]"#,
            "bound.jwt",
            "2099-05-01T00:00:00Z",
        )
        .await
        .unwrap());

        let row = get_agent_identity(&pool, "reg_prebound")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.did.as_deref(), Some(did));
        assert_eq!(row.status, AgentIdentityStatus::Claimed);
    }

    #[tokio::test]
    async fn claim_cannot_overwrite_an_existing_owner() {
        // Defense in depth: even a (mis)call that passes `Some(other_did)` for an already-owned
        // active registration must not rebind it — the SQL guard matches no rows.
        let pool = test_pool().await;
        let owner = "did:plc:agentauthclaim3333333";
        let intruder = "did:plc:agentauthclaim4444444";
        insert_account(&pool, owner).await;
        insert_account(&pool, intruder).await;

        insert_agent_identity(&pool, &new_identity("reg_owned", owner))
            .await
            .unwrap();

        assert!(!claim_agent_identity(
            &pool,
            "reg_owned",
            Some(intruder),
            r#"["atproto"]"#,
            "hijack.jwt",
            "2099-06-01T00:00:00Z",
        )
        .await
        .unwrap());

        // Owner and status are untouched.
        let row = get_agent_identity(&pool, "reg_owned")
            .await
            .unwrap()
            .unwrap();
        assert_eq!(row.did.as_deref(), Some(owner));
        assert_eq!(row.status, AgentIdentityStatus::Active);
    }
}

